-- TEC-20 Pass, set and play – combinazione con manichino (insert o aggiornamento)
insert into public.exercises (id, data, updated_at) values ('5eed0000-0000-4000-8000-00000000013e', '{"code":"TEC-20","title":"Pass, set and play – combinazione con manichino","area":"tecnica","fase":["attivazione"],"obiettivi":["passaggio","ricezione","uno-due","controllo orientato","postura del corpo"],"eta":"U9-U13","giocatori":"6-8 (2 stazioni)","spazio":"20x12 m","durata":10,"materiale":"2 paletti, 2 manichini, 4 cinesini, palloni","perche":"Attivazione con palla: qualità del passaggio, appoggio di ritorno (set), attacco dello spazio per ricevere in corsa e passaggio diagonale. Alza ritmo e intensità prima della parte centrale.","descrizione":"Setup: area 20x12 m con 2 stazioni. In ogni stazione una porta al centro formata da un paletto e un manichino (il manichino sul lato verso l’altra stazione), un cinesino a sinistra e uno a destra.\nEsecuzione: il giocatore a sinistra (9) passa attraverso la porta al compagno di fronte (5); 5 appoggia di ritorno nella stessa porta. 9 gioca il pallone all’esterno del manichino e 5 attacca lo spazio e lo riceve in corsa. 5 conduce e gioca in diagonale al giocatore a sinistra dell’altra stazione (11), poi segue il passaggio. Nella seconda stazione la stessa sequenza riparte nella direzione opposta (11 con 7) e la diagonale torna alla prima stazione.\nEsercizio continuo, ritmo alto.","rotazione":"Segui il passaggio: chi passa nella porta va sul cinesino di destra della sua stazione; chi riceve in corsa gioca la diagonale e va in fila sul cinesino di sinistra dell’altra stazione.","varianti":"Massimo 2 tocchi, poi 1 tocco. Solo piede debole. Più giocatori per stazione per aumentare i recuperi. Due palloni in contemporanea (uno per stazione).","coaching":"Passaggio forte e preciso nella porta. Set di prima, morbido, sul piede del compagno. Chi riceve parte in anticipo e riceve in corsa con postura aperta verso l’altra stazione. Diagonale tesa e precisa. Tenere il ritmo.","fonte":"Video drill “Pass, set and play” (inviato da Andrea, 23/10/2026)","diagram":{"field":{"preset":"spazio","w":20,"h":12},"steps":[{"title":"Passaggio nella porta","note":"9 passa a 5 tra paletto e manichino"},{"title":"Set","note":"5 appoggia di ritorno nella stessa porta"},{"title":"Fuori dal manichino","note":"9 gioca all’esterno del manichino, 5 riceve in corsa"},{"title":"Diagonale","note":"5 gioca in diagonale a 11 e segue il passaggio; 9 va a destra, 10 entra"},{"title":"Stazione 2: porta","note":"11 passa a 7"},{"title":"Set","note":"7 appoggia di ritorno"},{"title":"Fuori dal manichino","note":"11 gioca all’esterno del manichino, 7 riceve in corsa"},{"title":"Diagonale","note":"7 gioca in diagonale a 10 e segue il passaggio; 11 va a destra, 5 entra"},{"title":"Ricomincia"}],"items":[{"id":"it1101","type":"disc","pos":{"0":{"x":5,"y":0.6}}},{"id":"it1102","type":"disc","pos":{"0":{"x":5,"y":11.4}}},{"id":"it1103","type":"disc","pos":{"0":{"x":15,"y":0.6}}},{"id":"it1104","type":"disc","pos":{"0":{"x":15,"y":11.4}}},{"id":"it1105","type":"pole","pos":{"0":{"x":3.5,"y":6}}},{"id":"it1106","type":"mannequin","pos":{"0":{"x":6.5,"y":6}}},{"id":"it1107","type":"mannequin","pos":{"0":{"x":13.5,"y":6}}},{"id":"it1108","type":"pole","pos":{"0":{"x":16.5,"y":6}}},{"id":"it1109","type":"playerA","label":"9","pos":{"0":{"x":5,"y":3},"4":{"x":5,"y":10.5}}},{"id":"it1110","type":"playerA","label":"10","pos":{"0":{"x":5,"y":1.2},"4":{"x":5,"y":3}}},{"id":"it1111","type":"playerA","label":"5","pos":{"0":{"x":5,"y":10.5},"3":{"x":9,"y":7.9},"4":{"x":15.8,"y":1.2},"8":{"x":15,"y":3}}},{"id":"it1112","type":"playerA","label":"11","pos":{"0":{"x":15,"y":3},"8":{"x":15,"y":10.5}}},{"id":"it1113","type":"playerA","label":"7","pos":{"0":{"x":15,"y":10.5},"7":{"x":11,"y":7.9},"8":{"x":4.2,"y":1.2}}},{"id":"it1114","type":"playerA","label":"6","pos":{"0":{"x":16.6,"y":11.3}}},{"id":"it1115","type":"ball","pos":{"0":{"x":5.5,"y":3.2},"1":{"x":5,"y":9.9},"2":{"x":5.5,"y":3.2},"3":{"x":8.9,"y":7.3},"4":{"x":14.5,"y":3.2},"5":{"x":15,"y":9.9},"6":{"x":14.5,"y":3.2},"7":{"x":11.1,"y":7.3},"8":{"x":5.5,"y":3.2}}}],"arrows":[{"id":"ar1116","kind":"pass","step":0,"from":{"x":5.5,"y":3.2},"to":{"x":5,"y":9.9}},{"id":"ar1117","kind":"pass","step":1,"from":{"x":5,"y":9.9},"to":{"x":5.5,"y":3.2},"curve":0.8},{"id":"ar1118","kind":"pass","step":2,"from":{"x":5.5,"y":3.2},"to":{"x":8.9,"y":7.3},"curve":-2},{"id":"ar1119","kind":"run","step":2,"from":{"x":5,"y":10.5},"to":{"x":9,"y":7.9}},{"id":"ar1120","kind":"pass","step":3,"from":{"x":8.9,"y":7.3},"to":{"x":14.5,"y":3.2}},{"id":"ar1121","kind":"run","step":3,"from":{"x":9,"y":7.9},"to":{"x":15.8,"y":1.2},"curve":1},{"id":"ar1122","kind":"run","step":3,"from":{"x":5,"y":3},"to":{"x":5,"y":10.5},"curve":2.5},{"id":"ar1123","kind":"run","step":3,"from":{"x":5,"y":1.2},"to":{"x":5,"y":3}},{"id":"ar1124","kind":"pass","step":4,"from":{"x":14.5,"y":3.2},"to":{"x":15,"y":9.9}},{"id":"ar1125","kind":"pass","step":5,"from":{"x":15,"y":9.9},"to":{"x":14.5,"y":3.2},"curve":-0.8},{"id":"ar1126","kind":"pass","step":6,"from":{"x":14.5,"y":3.2},"to":{"x":11.1,"y":7.3},"curve":2},{"id":"ar1127","kind":"run","step":6,"from":{"x":15,"y":10.5},"to":{"x":11,"y":7.9}},{"id":"ar1128","kind":"pass","step":7,"from":{"x":11.1,"y":7.3},"to":{"x":5.5,"y":3.2}},{"id":"ar1129","kind":"run","step":7,"from":{"x":11,"y":7.9},"to":{"x":4.2,"y":1.2},"curve":-1},{"id":"ar1130","kind":"run","step":7,"from":{"x":15,"y":3},"to":{"x":15,"y":10.5},"curve":-2.5},{"id":"ar1131","kind":"run","step":7,"from":{"x":15.8,"y":1.2},"to":{"x":15,"y":3}}]},"id":"5eed0000-0000-4000-8000-00000000013e","updatedAt":"2026-10-01T00:00:00.000Z"}'::jsonb, now()) on conflict (id) do update set data = excluded.data, updated_at = now();
